-- WoDoom: DOOM E1M1 rendered from real WAD data (BSP, textures, sprites) as textured column strips.
-- Data and art are generated by tools/wad2wow.py.

local ADDON, ns = ...
local level, assets = ns.level, ns.assets

local floor, ceil, abs, sin, cos, sqrt, min, max, pi =
    math.floor, math.ceil, math.abs, math.sin, math.cos, math.sqrt, math.min, math.max, math.pi

-- Doom screen space is 320x200 with a 168-line 3D view; FX/FY scale it to frame pixels (4:3).
local SW, VIEWH, CX, CY = 320, 168, 160, 84
local SCALE = 160 -- projection scale for a 90 degree horizontal FOV
local COLS, COLW = 160, 2
local FX, FY = 2, 2.4
local FRAME_W, FRAME_H = SW * FX, 200 * FY
local TIC_RATE, TIC_TIME = 35, 1 / 35
local FAR, NEAR = 30000, 0.1

local EYE, RADIUS, STEP_H, BODY_H = 41, 16, 24, 56
local MAXMOVE, STOPSPEED, FRICTION = 30, 0x1000 / 65536, 0xe800 / 65536
local BAM = 4294967296
local USE_RANGE = 64

-- Doom's lighting: a sector's light level and the distance pick one of 32 colormaps; assets.cmap holds each map's RGB gain.
local Light = { gain = assets.cmap, extra = 0, chunk = 0, maxRegions = 5000 }
Light.presets = {
    dos = { cols = 320, chunk = 16, regions = 10000 }, -- full resolution, light varying across floor rows
    fast = { cols = 160, chunk = 0, regions = 5000 },
    hi = { cols = 320, chunk = 0, regions = 5000 },
}
Light.presets.lo = Light.presets.fast

function Light.pick(level)
    if level < 0 then level = 0 elseif level > 31 then level = 31 end
    return Light.gain[level + 1]
end

function Light.lightnum(li, contrast)
    local n = floor(li / 16) + Light.extra + (contrast or 0)
    if n < 0 then return 0 elseif n > 15 then return 15 end
    return n
end

-- Walls and sprites: the colormap index follows the scale, 2560 / depth (R_StoreWallRange and R_DrawVisSprite).
function Light.scaled(li, depth, contrast)
    local index = min(floor(2560 / depth), 47)
    return Light.pick((15 - Light.lightnum(li, contrast)) * 4 - floor(index / 2))
end

-- Floors and ceilings: the colormap index follows the distance along the ray (R_MapPlane).
function Light.span(li, distance)
    local j = min(floor(distance / 16), 127)
    return Light.pick((15 - Light.lightnum(li)) * 4 - floor(floor(160 / (j + 1)) / 2))
end

-- The weapon sprite uses the farthest scale step of its sector's light.
function Light.weapon(li)
    return Light.pick((15 - Light.lightnum(li)) * 4 - 23)
end

