local gameTime, ticCount, updateAccumulator = 0, 0, 0
local ANIM_SEQ = { "NUKAGE1", "NUKAGE2", "NUKAGE3" }
local ANIM_POS = { NUKAGE1 = 0, NUKAGE2 = 1, NUKAGE3 = 2 }

local function currentFlat(name)
    local pos = ANIM_POS[name]
    if pos then return ANIM_SEQ[(pos + floor(gameTime * 35 / 8)) % 3 + 1] end
    return name
end

local ssSector = {}
for i, ss in ipairs(ssectors) do ssSector[i] = segs[ss.first].f end
for _, s in ipairs(sectors) do s.fl0, s.ce0, s.li0 = s.fl, s.ce, s.li end
for _, s in ipairs(segs) do s.mi0, s.up0, s.lo0 = s.mi, s.up, s.lo end
for _, L in ipairs(lines) do
    L.minx, L.maxx = min(L.x1, L.x2), max(L.x1, L.x2)
    L.miny, L.maxy = min(L.y1, L.y2), max(L.y1, L.y2)
end

-- BSP queries -------------------------------------------------------------------------------------
local function subsectorAt(x, y)
    local n = ROOT
    while n > 0 do
        local node = nodes[n]
        if node.dx * (y - node.y) - node.dy * (x - node.x) < 0 then n = node.r else n = node.l end
    end
    return -n
end

local function sectorAt(x, y)
    return ssSector[subsectorAt(x, y)]
end

-- Collision and line queries -------------------------------------------------------------------------
local function distToSeg2(px, py, x1, y1, x2, y2)
    local dx, dy = x2 - x1, y2 - y1
    local l2 = dx * dx + dy * dy
    local t = l2 > 0 and ((px - x1) * dx + (py - y1) * dy) / l2 or 0
    if t < 0 then t = 0 elseif t > 1 then t = 1 end
    local ex, ey = x1 + t * dx - px, y1 + t * dy - py
    return ex * ex + ey * ey
end

local function lineBlocksMove(L, curFloor)
    if L.bs == 0 or L.fl % 2 == 1 then return true end
    local F, B = sectors[L.fs], sectors[L.bs]
    local open = min(F.ce, B.ce) - max(F.fl, B.fl)
    return open < BODY_H or max(F.fl, B.fl) - curFloor > STEP_H
end

local solids, actors = {}, {}

local function canMove(x, y, curFloor, r)
    local r2 = r * r
    for i = 1, #lines do
        local L = lines[i]
        if x > L.minx - r and x < L.maxx + r and y > L.miny - r and y < L.maxy + r
            and distToSeg2(x, y, L.x1, L.y1, L.x2, L.y2) < r2 and lineBlocksMove(L, curFloor) then
            return false
        end
    end
    return true
end

local function blockedBySolid(x, y, r, self)
    for i = 1, #solids do
        local s = solids[i]
        if s ~= self and not s.gone then
            local dx, dy = s.x - x, s.y - y
            local rr = s.r + r
            if dx * dx + dy * dy < rr * rr then return true end
        end
    end
    for _, a in ipairs(actors) do
        if a ~= self and a.mon and a.hp > 0 then
            local dx, dy = a.x - x, a.y - y
            local rr = 20 + r
            if dx * dx + dy * dy < rr * rr then return true end
        end
    end
    return false
end

-- First blocking wall along a unit ray (closed doors and one-sided lines).
local function rayWall(px, py, dx, dy)
    local best = FAR
    for i = 1, #lines do
        local L = lines[i]
        local blocks = L.bs == 0
        if not blocks then
            local F, B = sectors[L.fs], sectors[L.bs]
            blocks = min(F.ce, B.ce) - max(F.fl, B.fl) <= 0
        end
        if blocks then
            local ex, ey = L.x2 - L.x1, L.y2 - L.y1
            local denom = dx * ey - dy * ex
            if abs(denom) > 1e-9 then
                local ax, ay = L.x1 - px, L.y1 - py
                local t = (ax * ey - ay * ex) / denom
                local s = (ax * dy - ay * dx) / denom
                if t > 0 and t < best and s >= 0 and s <= 1 then best = t end
            end
        end
    end
    return best
end

local function hasLOS(x1, y1, x2, y2)
    local dx, dy = x2 - x1, y2 - y1
    local d = sqrt(dx * dx + dy * dy)
    if d < 1 then return true end
    return rayWall(x1, y1, dx / d, dy / d) >= d
end

