    seconds = 0, par = 30, back = "title", stack = {}, showMessages = true }

function SKILLS.monster(m)
    if not SKILLS[skill].fast then return m end
    local fast = {}
    for k, v in pairs(m) do fast[k] = v end
    fast.reaction, fast.chaseTics, fast.attack = 0, max(1, floor(m.chaseTics / 2)), {}
    for i, step in ipairs(m.attack) do fast.attack[i] = { step[1], max(1, floor(step[2] / 2)) } end
    return fast
end

